import unicodedata
import re

def normalize_name(name):
    name = unicodedata.normalize("NFKD", name).encode("ascii", "ignore").decode("ascii")
    return name


def getUniqueNames(names):
    uniqueNames = {}
    for name in names:
        normalized_name = normalize_name(name)
        if re.search(r'https?://', normalized_name):
            continue
        if normalized_name not in uniqueNames:
            uniqueNames[normalized_name] = True
    return list(uniqueNames.keys())

