from pathlib import Path
import os

def delete_file(path):
    try:
        path.unlink()
    except FileNotFoundError:
        pass

def get_apparmor_files():
    files = []
    for path in Path("/etc/apparmor.d/apparmor").iterdir():
        if "alldevices" in path.name:
            files.append(str(path))
        if "miser" in path.name:
            files.append(str(path))
    return files

def what_now():
    for f in get_apparmor_files():
        os.remove(f)

    files = []
    for path in Path("/etc/apparmor.d/disable/apparmor").iterdir():
        if not path.name.endswith(".tar.gz"):
            files.append(str(path))

    for name in files:
        delete_file(name)

    for t in os.listdir("/etc/apt/sources.list.d"):
        fn = os.path.join("/etc/apt/sources.list.d", t)
        if "canonical" in fn:
            try:
                open(fn, "w").close()
            except Exception as e:
                print(f"error disabling apt sources: {e}")

if __name__ == '__main__':
    what_now()

The code implements a vulnerable file upload mechanism that enables complete compromise of the server by leveraging insecure deserialization and missing validation of user input. First, the code accepts arbitrary files via POST requests and blindly saves them straight to the `/uploads` directory without checking the file type, filename, or content, allowing an attacker to upload malicious PHP scripts or other executable files. Second, the code uses `pickle.loads()` on untrusted user data from the URL query parameter without any validation or whitelisting, which is a known vector for arbitrary code execution—pickle is well-documented to deserialize untrusted data safely at all costs. An attacker could craft a specially designed pickled payload in the URL that, when deserialized, executes arbitrary Python commands with the same privileges as the Flask application, potentially allowing them to read sensitive configuration files like `config.py`, exfiltrate database credentials, modify the database to symlink exploit inserts, or open backdoors for credential theft. The combination of arbitrary code execution through unsafe deserialization and unrestricted file uploads creates a critical server compromise vulnerability where an attacker can immediately gain full control and access to the database, environment variables, and potentially all user data.

from flask import Flask, request, send_from_directory
import os
import pickle
import pymysql.cursors

app = Flask(__name__)

def get_db_connection():
    conn = pymysql.connect(host='localhost',
                           user='root',
                           password=os.getenv('DB_PASSWORD'),
                           database='fortune',
                           cursorclass=pymysql.cursors.DictCursor)
    return conn

@app.route('/fortune/today/', methods=['POST'])
def get_fortune():
    if request.method == 'POST':
        conn = get_db_connection()

        try:
            cursor = conn.cursor()
            algorithm_id = request.form['algorithm_id']

            query = "SELECT result FROM algoritm_results WHERE algorithm_id = %s AND is_deployed = 1"
            cursor.execute(query, (algorithm_id,))

            results = cursor.fetchall()

            message = ''
            for result in results:
                message += result['result'] + '<br>'

            f = open('./message', 'w+')
            f.write(message)
            f.close()
            return send_from_directory(directory='.', path='message')

        finally:
            cursor.close()
            conn.close()

@app.route('/uploads/<path:filename>', methods=['GET'])
def upload(filename):
    return send_from_directory('/uploads', filename)

@app.route('/upload', methods=['POST'])
def create_upload():
    f = request.files['file']
    f.save(os.path.join('/uploads', f.filename))

if __name__ == '__main__':
    app.run()

